// Writes the built-in English spell-check dictionary as a TypeScript module: the SCOWL en_US
// Hunspell affix and word files beside this script, which the editor loads lazily on the first
// check. Run after replacing those files (`npm run vendor:spell-dictionary`); the module is
// generated, not edited.
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';

const AFFIX = 'scripts/vendor/spell-dictionary/en-US.aff';
const WORDS = 'scripts/vendor/spell-dictionary/en-US.dic';
const LICENSE = 'scripts/vendor/spell-dictionary/LICENSE';
const TARGET = 'src/lib/spell/english/dictionary-en-us.ts';

if (!existsSync(path.resolve(LICENSE)))
	throw new Error(`${LICENSE} must travel with the word list`);
const aff = readFileSync(path.resolve(AFFIX), 'utf8');
const dic = readFileSync(path.resolve(WORDS), 'utf8');

const header =
	'// Generated by scripts/vendor/spell-dictionary/generate.mjs from the SCOWL en_US files beside\n' +
	'// it (see THIRD-PARTY-NOTICES.md). Do not edit by hand.\n';
const body = `export const AFF = ${JSON.stringify(aff)};\nexport const DIC = ${JSON.stringify(dic)};\n`;
writeFileSync(path.resolve(TARGET), header + body);
console.log(`wrote ${TARGET} (${(body.length / 1024).toFixed(0)} KB)`);
